// A component's design-system page (remediation Part 4.2): the live example with its controls, then the guidance
// (app/src/docs/<slug>.md, hand-written) and the API (app/src/docs/api/<slug>.json, generated by scripts/gen-docs.mjs).
import { marked } from "marked";
import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { CodeBlock } from "../../../src/elements/react";
import { ENTRIES, type Entry } from "../registry";
import { BrowserSupportSection, FrameworkTabs, FrameworksSection, Imports, Inline, PerformanceSection, Table, dash, kb } from "./DocsSections";
import { GUIDANCE, PATTERNS, type AnatomyPart, type Guidance } from "./guidance";
import { FRAMEWORKS, snippets, type ApiElement, type ApiPage } from "./usage";

const API = import.meta.glob<ApiPage>("./api/*.json", { import: "default" });

/** The sections a page can have, in order: [anchor, title] */
const SECTIONS: [string, string][] = [
  ["example", "Example"],
  ["overview", "Overview"],
  ["anatomy", "Anatomy"],
  ["looks", "Looks"],
  ["theme", "Theme"],
  ["usage", "Usage"],
  ["api", "API"],
  ["frameworks", "Frameworks"],
  ["accessibility", "Accessibility"],
  ["browser-support", "Browser support"],
  ["performance", "Performance"],
  ["content", "Content"],
  ["do-dont", "Do and don't"],
  ["related", "Related"],
  ["changelog", "Changelog"],
];

const md = (text: string) => ({ __html: marked.parse(text, { async: false }) as string });

export function DocsPage({ entry, section, example }: { entry: Entry; section: string; example: ReactNode }) {
  const [api, setApi] = useState<ApiPage | null>(null);
  const guide: Guidance | undefined = GUIDANCE[entry.slug];
  useEffect(() => {
    setApi(null);
    void API[`./api/${entry.slug}.json`]?.().then(setApi);
  }, [entry.slug]);

  // A deep link (#/<id>/<section>) scrolls to its section once the page has rendered
  useEffect(() => {
    if (!section) {
      window.scrollTo(0, 0);
      return;
    }
    const t = setTimeout(() => document.getElementById(`docs-${section}`)?.scrollIntoView({ block: "start" }), 60);
    return () => clearTimeout(t);
  }, [entry.id, section, api]);

  // "On this page" follows the scroll: the last section whose heading has passed the top bar
  const [inView, setInView] = useState("example");
  useEffect(() => {
    const onScroll = () => {
      const heads = [...document.querySelectorAll<HTMLElement>(".docs-section")];
      const passed = heads.filter((h) => h.getBoundingClientRect().top < 120);
      setInView((passed[passed.length - 1] ?? heads[0])?.id.replace(/^docs-/, "") ?? "example");
    };
    onScroll();
    addEventListener("scroll", onScroll, { passive: true });
    return () => removeEventListener("scroll", onScroll);
  }, [entry.id, api]);

  const main = api?.elements[0];
  const present = SECTIONS.filter(([id]) => has(id, guide, api));
  const status = guide?.status ?? (entry.library === "components" ? "stable" : "stable");

  return (
    <div className="docs">
      <article className="docs-body">
        <header className="docs-head">
          <div className="docs-eyebrow">
            {entry.category}
            {status !== "stable" && <span className={`docs-status ${status}`}>{status === "new" ? "New" : "Also in React"}</span>}
          </div>
          <h1>{entry.name}</h1>
          <p className="docs-lede">
            <Inline text={entry.description} />
          </p>
          {main && (
            <dl className="docs-meta">
              <div>
                <dt>Element</dt>
                <dd>
                  {api!.elements.map((e) => (
                    <code key={e.tag}>&lt;{e.tag}&gt;</code>
                  ))}
                </dd>
              </div>
              {api!.size && (
                <div>
                  <dt>Size</dt>
                  <dd>
                    {kb(api!.size.gzip)} gzip <span className="muted">· {kb(api!.size.min)} min, on a page that has Lit ·</span>{" "}
                    <a className="docs-link" href={`#/${entry.id}/performance`}>Performance</a>
                  </dd>
                </div>
              )}
              {api!.browser && (
                <div>
                  <dt>Works in</dt>
                  <dd>
                    Chrome / Edge {api!.browser.floor.chrome}+, Firefox {api!.browser.floor.firefox}+, Safari {api!.browser.floor.safari}+ <span className="muted">·</span>{" "}
                    <a className="docs-link" href={`#/${entry.id}/browser-support`}>Browser support</a>
                  </dd>
                </div>
              )}
            </dl>
          )}
          {main && <Imports slug={entry.slug} api={api!} />}
        </header>

        <Section id="example" title="Example" anchorOf={entry.id}>
          <LiveExample entry={entry} anatomy={guide?.anatomy ?? []}>
            {example}
          </LiveExample>
        </Section>

        {guide?.sections.Overview && (
          <Section id="overview" title="Overview" anchorOf={entry.id}>
            <div className="docs-md" dangerouslySetInnerHTML={md(guide.sections.Overview)} />
            <div className="docs-when">
              {guide.sections["When to use"] && (
                <div className="docs-when-col use">
                  <h3>When to use</h3>
                  <div className="docs-md" dangerouslySetInnerHTML={md(guide.sections["When to use"])} />
                </div>
              )}
              {guide.sections["When not to use"] && (
                <div className="docs-when-col avoid">
                  <h3>When not to use</h3>
                  <div className="docs-md" dangerouslySetInnerHTML={md(linkSlugs(guide.sections["When not to use"]))} />
                </div>
              )}
            </div>
          </Section>
        )}

        {guide && guide.anatomy.length > 0 && (
          <Section id="anatomy" title="Anatomy" anchorOf={entry.id}>
            <p className="muted docs-hint">Turn on “Show anatomy” on the example to see each part numbered on the live component.</p>
            <ol className="docs-anatomy">
              {guide.anatomy.map((p) => (
                <li key={p.n}>
                  <span className="docs-pin">{p.n}</span>
                  <div>
                    <strong>{p.label}</strong>
                    {p.text && <span dangerouslySetInnerHTML={{ __html: ` – ${marked.parseInline(p.text, { async: false }) as string}` }} />}
                  </div>
                </li>
              ))}
            </ol>
          </Section>
        )}

        {guide?.sections.Looks && (
          <Section id="looks" title="Looks" anchorOf={entry.id}>
            <div className="docs-md" dangerouslySetInnerHTML={md(guide.sections.Looks)} />
          </Section>
        )}

        {guide?.sections.Theme && (
          <Section id="theme" title="Theme" anchorOf={entry.id}>
            <div className="docs-md" dangerouslySetInnerHTML={md(guide.sections.Theme)} />
          </Section>
        )}

        {main && (
          <Section id="usage" title="Usage" anchorOf={entry.id}>
            <Usage slug={entry.slug} el={main} guide={guide} api={api!} />
          </Section>
        )}

        {api && (
          <Section id="api" title="API" anchorOf={entry.id}>
            {api.elements.map((el) => (
              <ElementApi key={el.tag} el={el} several={api.elements.length > 1} singleLook={entry.library !== "components"} />
            ))}
            {api.functions && api.functions.length > 0 && (
              <div className="docs-api">
                <h4>Functions</h4>
                <p className="docs-hint muted">Exported from the module next to the element.</p>
                <Table label={"Functions"} head={["Function", "Description"]} rows={api.functions.map((f) => [<code key="s" className="docs-type">{f.signature}</code>, <Inline key="d" text={f.description} />])} />
              </div>
            )}
          </Section>
        )}

        {main && api && (
          <Section id="frameworks" title="Frameworks" anchorOf={entry.id}>
            <FrameworksSection
              slug={entry.slug}
              api={api}
              reactTable={
                api.react.some((r) => r.exported) ? (
                  <>
                    <h3 className="docs-sub">React props</h3>
            <p className="docs-hint muted">
                      The wrapper takes every element property above under the same name, plus these. Values with a <code>default…</code> twin are
                      controlled when given and kept by the element otherwise.
                    </p>
                    {api.react
                      .filter((r) => r.exported)
                      .map((r) => (
                        <div key={r.component}>
                          {api.react.filter((x) => x.exported).length > 1 && <h3 className="docs-sub">{r.component}</h3>}
                          <Table
                            label={`${r.component} props`} head={["Prop", "Type", "Description"]}
                            rows={r.props.map((p) => [<code key="n">{p.name + (p.optional ? "" : "")}</code>, <code key="t" className="docs-type">{p.type}</code>, p.description ? <Inline key="d" text={p.description} /> : <span className="muted">–</span>])}
                          />
                          {r.hides.length > 0 && (
                            <p className="docs-hint muted">
                              Renamed or hidden on the wrapper: {r.hides.map((h) => <code key={h}>{h}</code>).reduce<ReactNode[]>((a, c, i) => (i ? [...a, ", ", c] : [c]), [])}
                            </p>
                          )}
                        </div>
                      ))}
                  </>
                ) : null
              }
            />
          </Section>
        )}

        {(guide?.sections.Keyboard || guide?.sections["Screen readers"] || main) && (
          <Section id="accessibility" title="Accessibility" anchorOf={entry.id}>
            {guide && guide.pattern !== "none" && PATTERNS[guide.pattern] && (
              <p>
                Follows the WAI-ARIA <a className="docs-link" href={PATTERNS[guide.pattern].url} target="_blank" rel="noreferrer">{PATTERNS[guide.pattern].name} pattern</a>.
              </p>
            )}
            {guide?.sections.Keyboard && (
              <>
                <h3 className="docs-sub">Keyboard</h3>
                <div className="docs-md" dangerouslySetInnerHTML={md(guide.sections.Keyboard)} />
              </>
            )}
            {guide?.sections["Screen readers"] && (
              <>
                <h3 className="docs-sub">Screen readers</h3>
                <div className="docs-md" dangerouslySetInnerHTML={md(guide.sections["Screen readers"])} />
              </>
            )}
            <h3 className="docs-sub">{entry.library === "components" ? "Every component" : "Every piece"}</h3>
            <ul className="docs-guarantees">
              <li>Passes axe (WCAG 2.2 A and AA){entry.library === "components" ? " in both looks," : ""} light and dark, in Chromium, Firefox and WebKit.</li>
              <li>Forced colours (Windows High Contrast): controls keep a system-colour border, selection is Highlight, focus shows an outline.</li>
              <li>Reduced motion: animations stop or shorten under <code>prefers-reduced-motion</code>.</li>
              <li>Not yet tested with a screen reader by a person (VoiceOver, NVDA).</li>
            </ul>
          </Section>
        )}

        {api?.browser && (
          <Section id="browser-support" title="Browser support" anchorOf={entry.id}>
            <BrowserSupportSection api={api} singular={entry.library === "components" ? "the component" : "the piece"} />
          </Section>
        )}

        {api && (
          <Section id="performance" title="Performance" anchorOf={entry.id}>
            <PerformanceSection slug={entry.slug} entryId={entry.id} api={api} library={entry.library} />
          </Section>
        )}

        {guide?.sections.Content && (
          <Section id="content" title="Content" anchorOf={entry.id}>
            <div className="docs-md" dangerouslySetInnerHTML={md(guide.sections.Content)} />
          </Section>
        )}

        {(guide?.sections.Do || guide?.sections["Don't"]) && (
          <Section id="do-dont" title="Do and don't" anchorOf={entry.id}>
            <div className="docs-dodont">
              {guide.sections.Do && (
                <div className="docs-do">
                  <h3>Do</h3>
                  <div className="docs-md" dangerouslySetInnerHTML={md(guide.sections.Do)} />
                </div>
              )}
              {guide.sections["Don't"] && (
                <div className="docs-dont">
                  <h3>Don't</h3>
                  <div className="docs-md" dangerouslySetInnerHTML={md(guide.sections["Don't"])} />
                </div>
              )}
            </div>
          </Section>
        )}

        {guide && guide.related.length > 0 && (
          <Section id="related" title="Related" anchorOf={entry.id}>
            <div className="docs-related">
              {guide.related.map((slug) => {
                const e = ENTRIES.find((x) => x.slug === slug);
                return e ? (
                  <a key={slug} href={`#/${e.id}`} className="docs-related-card">
                    <strong>{e.name}</strong>
                    <span className="muted">{e.description}</span>
                  </a>
                ) : null;
              })}
            </div>
          </Section>
        )}

        {api && api.changelog.length > 0 && (
          <Section id="changelog" title="Changelog" anchorOf={entry.id}>
            <ul className="docs-changelog">
              {api.changelog.map((line, i) => (
                <li key={i} dangerouslySetInnerHTML={{ __html: marked.parseInline(line, { async: false }) as string }} />
              ))}
            </ul>
          </Section>
        )}
      </article>

      <nav className="docs-toc" aria-label="On this page">
        <div className="docs-toc-title">On this page</div>
        {present.map(([id, title]) => (
          <a key={id} href={`#/${entry.id}/${id}`} className={inView === id ? "active" : ""} aria-current={inView === id ? "location" : undefined}>
            {title}
          </a>
        ))}
      </nav>
    </div>
  );
}

function has(id: string, guide: Guidance | undefined, api: ApiPage | null) {
  const s = guide?.sections ?? {};
  switch (id) {
    case "example":
      return true;
    case "overview":
      return !!s.Overview;
    case "anatomy":
      return !!guide?.anatomy.length;
    case "looks":
      return !!s.Looks;
    case "theme":
      return !!s.Theme;
    case "usage":
    case "api":
      return !!api?.elements.length;
    case "frameworks":
      return !!api?.elements.length;
    case "browser-support":
      return !!api?.browser;
    case "performance":
      return !!api;
    case "accessibility":
      return true;
    case "content":
      return !!s.Content;
    case "do-dont":
      return !!(s.Do || s["Don't"]);
    case "related":
      return !!guide?.related.length;
    case "changelog":
      return !!api?.changelog.length;
  }
  return false;
}

/** Component names in prose become links to their pages: `command-menu` → the Command Menu page */
function linkSlugs(text: string) {
  return text.replace(/`([a-z][a-z0-9-]+)`/g, (whole, slug: string) => {
    const e = ENTRIES.find((x) => x.slug === slug);
    return e ? `[${e.name}](#/${e.id})` : whole;
  });
}

function Section({ id, title, anchorOf, children }: { id: string; title: string; anchorOf: string; children: ReactNode }) {
  return (
    <section className="docs-section" id={`docs-${id}`} aria-labelledby={`docs-${id}-h`}>
      <h2 id={`docs-${id}-h`}>
        <a href={`#/${anchorOf}/${id}`} className="docs-anchor" aria-label={`Link to ${title}`}>
          #
        </a>
        {title}
      </h2>
      {children}
    </section>
  );
}

function ElementApi({ el, several, singleLook }: { el: ApiElement; several: boolean; singleLook: boolean }) {
  const [showTokens, setShowTokens] = useState(false);
  return (
    <div className="docs-api">
      {several && (
        <h3 className="docs-sub">
          <code>&lt;{el.tag}&gt;</code>
        </h3>
      )}
      {several && el.description && <p className="muted docs-hint">{el.description}</p>}
      <h4>Properties and attributes</h4>
      <Table
        label={`${el.tag} properties`} head={["Property", "Attribute", "Type", "Default", "Description"]}
        rows={el.properties.filter((p) => !(singleLook && p.name === "look")).map((p) => [
          <code key="n">{p.name}</code>,
          p.attribute ? <code key="a">{p.attribute}</code> : dash,
          <code key="t" className="docs-type">{p.type}</code>,
          p.default ? <code key="d">{p.default}</code> : dash,
          p.description ? <Inline key="d" text={p.description} /> : dash,
        ])}
      />
      {el.events.length > 0 && (
        <>
          <h4>Events</h4>
          <Table
            label={`${el.tag} events`} head={["Event", "Detail", "Cancelable", "Description"]}
            rows={el.events.map((e) => [<code key="n">{e.name}</code>, e.detail ? <code key="d" className="docs-type">{e.detail}</code> : dash, e.cancelable ? "Yes" : "No", e.description ? <Inline key="d" text={e.description} /> : dash])}
          />
        </>
      )}
      {el.slots.length > 0 && (
        <>
          <h4>Slots</h4>
          <Table label={`${el.tag} slots`} head={["Slot", "Description"]} rows={el.slots.map((s) => [<code key="n">{s.name}</code>, s.description ? <Inline key="d" text={s.description} /> : dash])} />
        </>
      )}
      {el.methods.length > 0 && (
        <>
          <h4>Methods</h4>
          <Table
            label={`${el.tag} methods`} head={["Method", "Returns", "Description"]}
            rows={el.methods.map((m) => [<code key="n">{`${m.name}(${m.params})`}</code>, <code key="r" className="docs-type">{m.returns}</code>, m.description ? <Inline key="d" text={m.description} /> : dash])}
          />
        </>
      )}
      {el.cssProperties.length > 0 && (
        <>
          <h4>Component tokens</h4>
          <p className="docs-hint muted">Custom properties on the element – set them on the element or an ancestor to adjust it.</p>
          <Table
            label={`${el.tag} component tokens`} head={["Custom property", "Value", "Look"]}
            rows={el.cssProperties.map((c) => [
              <code key="n">{c.name}</code>,
              <code key="v" className="docs-type">{c.value}</code>,
              c.fallback ? <span key="l" className="muted">not set – this fallback applies</span> : c.looks.join(", "),
            ])}
          />
        </>
      )}
      {el.tokens.length > 0 && (
        <>
          <h4>Design tokens it reads</h4>
          <button type="button" className="ghost docs-more" aria-expanded={showTokens} onClick={() => setShowTokens((v) => !v)}>
            {showTokens ? "Hide" : `Show all ${el.tokens.length}`}
          </button>
          {showTokens && (
            <div className="docs-tokens">
              {el.tokens.map((t) => (
                <code key={t}>{t}</code>
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
}

function Usage({ slug, el, guide, api }: { slug: string; el: ApiElement; guide?: Guidance; api: ApiPage }) {
  const code = useMemo(() => snippets(slug, el, guide?.examples ?? {}, api.react.find((r) => r.exported), api.frameworks?.[0]), [slug, el, guide, api]);
  return (
    <div className="docs-usage">
      <FrameworkTabs id={`usage-${slug}`}>
        {(fw) => (
          <>
            <CodeBlock key={fw} code={code[fw]} language={FRAMEWORKS.find(([f]) => f === fw)![3]} look="clean" lineNumbers={false} wrap />
            {((fw === "html" && !guide?.examples.html) || (fw === "react" && !guide?.examples.tsx) || fw === "vue" || fw === "angular" || fw === "svelte") && (
              <p className="docs-hint muted">
                Generated from the element's API and compiled in <code>examples/{fw}</code> by <code>npm run check:snippets</code>. The Frameworks section below covers events,
                control, slots, server rendering and types.
              </p>
            )}
          </>
        )}
      </FrameworkTabs>
    </div>
  );
}

const stopPresses = (el: HTMLElement | null) => {
  if (!el || el.dataset.stops) return;
  el.dataset.stops = "1";
  for (const type of ["pointerdown", "mousedown", "touchstart"]) el.addEventListener(type, (e) => e.stopPropagation());
};

/** The live example, with width presets and the anatomy overlay */
function LiveExample({ entry, anatomy, children }: { entry: Entry; anatomy: AnatomyPart[]; children: ReactNode }) {
  const [width, setWidth] = useState<"320" | "480" | "full">("full");
  const [showAnatomy, setShowAnatomy] = useState(false);
  const wrap = useRef<HTMLDivElement>(null);
  const [pins, setPins] = useState<{ n: number; x: number; y: number; w: number; h: number }[]>([]);

  useEffect(() => {
    setShowAnatomy(false);
    setWidth("full");
  }, [entry.id]);

  // Numbered pins over the first stage's parts; re-placed while shown, as the demo moves
  useEffect(() => {
    if (!showAnatomy || !anatomy.length) {
      setPins([]);
      return;
    }
    /** Shown, not just laid out: no ancestor up to the stage is transparent or hidden */
    const visible = (el: Element, stage: Element) => {
      for (let n: Element | null = el; n && n !== stage; n = n.parentElement) {
        const cs = getComputedStyle(n);
        if (cs.visibility === "hidden" || cs.display === "none" || Number(cs.opacity) === 0) return false;
      }
      return true;
    };
    const place = () => {
      const box = wrap.current;
      if (!box) return;
      const stages = [...box.querySelectorAll(".stage")];
      const origin = box.getBoundingClientRect();
      setPins(
        anatomy.flatMap((p) => {
          // The first stage where the part is on screen – a part only one look draws is pinned in that look
          for (const stage of stages) {
            const el = [...stage.querySelectorAll(p.selector)].find((x) => {
              const r = x.getBoundingClientRect();
              return (r.width || r.height) && visible(x, stage);
            });
            if (!el) continue;
            const r = el.getBoundingClientRect();
            return [{ n: p.n, x: r.left - origin.left, y: r.top - origin.top, w: r.width, h: r.height }];
          }
          return [];
        }),
      );
    };
    place();
    const t = setInterval(place, 400);
    return () => clearInterval(t);
  }, [showAnatomy, anatomy, entry.id]);

  return (
    <div className="docs-example">
      {/* The bar's presses don't reach the page, so a demo's open popup doesn't take them for an outside click */}
      <div className="docs-example-bar" ref={stopPresses}>
        <div className="seg" role="radiogroup" aria-label="Preview width">
          {(["320", "480", "full"] as const).map((w) => (
            <button key={w} role="radio" aria-checked={width === w} className={width === w ? "on" : ""} onClick={() => setWidth(w)}>
              {w === "full" ? "Full" : `${w} px`}
            </button>
          ))}
        </div>
        {anatomy.length > 0 && (
          <button type="button" className={`ghost ${showAnatomy ? "on" : ""}`} aria-pressed={showAnatomy} onClick={() => setShowAnatomy((v) => !v)}>
            Show anatomy
          </button>
        )}
      </div>
      <div ref={wrap} className="docs-example-stage">
        <div className="docs-example-inner" style={width === "full" ? undefined : { ["--docs-w" as string]: `${width}px` }} data-narrow={width !== "full" || undefined}>
          {children}
        </div>
        {pins.map((p) => (
          <span key={`${p.n}-${p.x}`} className="docs-pin-box" style={{ left: p.x, top: p.y, width: p.w, height: p.h }} aria-hidden="true">
            <span className="docs-pin">{p.n}</span>
          </span>
        ))}
      </div>
    </div>
  );
}
